<?php session_start();?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuryer kabineti • Fast Food</title><style>body{margin:0;font-family:system-ui;background:#f6f7fb;color:#101828}.wrap{max-width:900px;margin:auto;padding:20px}.card{background:#fff;border:1px solid #e4e7ec;border-radius:20px;padding:20px;margin:14px 0;box-shadow:0 12px 35px #1018280d}input,button{width:100%;padding:12px;border-radius:12px;border:1px solid #ddd;margin:6px 0;font:inherit;box-sizing:border-box}button{background:#ff4d00;color:#fff;border:0;font-weight:800}.order{border:1px solid #eee;border-radius:16px;padding:15px;margin:10px 0}.muted{color:#667085}</style></head><body><div class="wrap"><div class="card"><h1>🛵 Kuryer kabineti</h1><div id="app"></div></div></div><script>const api=(a,o={})=>fetch('courier_api.php?action='+a,o).then(r=>r.json()),A=document.querySelector('#app');async function boot(){let m=await api('me');if(!m.ok){A.innerHTML='<form id="f"><input name="phone" placeholder="Telefon" required><input name="pin" placeholder="PIN" type="password" required><button>Kirish</button></form>';f.onsubmit=async e=>{e.preventDefault();let d=await api('login',{method:'POST',body:new FormData(e.target)});d.ok?location.reload():alert(d.message)};return}A.innerHTML='<h3>Salom, '+m.data.name+' 🟢 Online</h3><button onclick="logout()">Chiqish</button><div id="orders">Yuklanmoqda...</div>';load()}async function load(){let d=await api('orders');document.querySelector('#orders').innerHTML=(d.data||[]).map(x=>'<div class="order"><b>#'+x.id+' — '+x.customer_name+'</b><p>📞 '+x.phone+'<br>📍 '+(x.address||'')+'<br>💰 '+Number(x.amount).toLocaleString('uz-UZ')+' so‘m</p><p class="muted">'+(x.note||'')+'</p><button onclick="st('+x.id+',\'delivering\')">Yo‘lda</button><button onclick="st('+x.id+',\'completed\')">Yetkazildi</button></div>').join('')||'<p class="muted">Sizga biriktirilgan buyurtma yo‘q.</p>'}async function st(id,s){let f=new FormData();f.append('order_id',id);f.append('status',s);await api('status',{method:'POST',body:f});load()}async function logout(){await api('logout');location.reload()}boot();setInterval(load,7000)</script></body></html>